// an id it lacks renders the English until it is translated (backfilled in
// batches; docs/frontend/i18n/README.md), and an id en no longer has is a
// compile error.
//
// Terms and style: docs/frontend/i18n/es-pt-br.md. Neutral Spanish for every
// region, addressing the reader as tú; sentence case; product nouns are
// Spanish (agente, computadora, servidor) and brand forms (Raft, Raft
// Computer, Raft Desktop, …) stay Latin. Plurals use `one` and `other`.

