  "settings.slackBridge.privateReauthorizationHint": 'Para seleccionar canales privados de Slack, un administrador del servidor debe actualizar la autorización de Slack con una cuenta que pertenezca a esos canales.',
  "settings.slackBridge.authorizerMissingTitle": 'Los canales privados necesitan una nueva autorización de Slack',
  "settings.slackBridge.authorizerMissingDescription": 'Esta conexión se autorizó antes de que Raft registrara quién la autorizó, así que Raft no puede confirmar que esa persona vea los canales privados vinculados, y esos pares dejaron de sincronizarse. Reintentar la comprobación no lo soluciona. Actualiza la autorización de Slack con una cuenta que pertenezca a esos canales.',
  "settings.slackBridge.authorizerMissingReadOnly": 'Esta conexión se autorizó antes de que Raft registrara quién la autorizó, así que Raft no puede confirmar que esa persona vea los canales privados vinculados, y esos pares dejaron de sincronizarse. Un propietario o administrador del servidor debe actualizar la autorización de Slack con una cuenta que pertenezca a esos canales.',
  "settings.slackBridge.reauthorize": "Actualizar autorización de Slack",
  "settings.slackBridge.oauthReturn.title": "La autorización de Slack no se completó",
  "settings.slackBridge.oauthReturn.cancelled": "La autorización se canceló o se rechazó en Slack. No se cambió nada; puedes intentarlo de nuevo.",
  "settings.slackBridge.oauthReturn.retryable": "Slack no estaba disponible temporalmente. No se cambió nada; inténtalo de nuevo en unos minutos.",
  "settings.slackBridge.oauthReturn.unconfirmed": "Raft no pudo confirmar si Slack completó la autorización. Actualiza esta página en un minuto y revisa el estado actual antes de volver a intentarlo.",
  "settings.slackBridge.oauthReturn.identityConflict": "Autorizaste un espacio de trabajo (o una app) de Slack distinto del que ya está conectado a este servidor de Raft. Autoriza el mismo espacio de trabajo o desconéctalo primero.",
  "settings.slackBridge.oauthReturn.failed": "La autorización de Slack no se completó y no se cambió nada. Inténtalo de nuevo; si sigue fallando, contacta al soporte de Raft e indica el código {code}.",
  "settings.slackBridge.disconnectDescription": "Al desconectar se revocan la credencial de Slack de este servidor de Raft, todas las vinculaciones de canales, las autorizaciones de envío y los vínculos de identidad. La app no se desinstala de Slack; para volver a conectar se necesita una nueva autorización.",
