  "settings.slackBridge.membershipRecoveryUnknownTitle": "El acceso al canal de Slack requiere atención",
  "settings.slackBridge.membershipRecoveryUnknownDescription": "La sincronización de mensajes está en pausa porque Raft no pudo verificar el acceso a un canal de Slack vinculado. Confirma que la app de Raft sigue en el canal y luego actualiza y vuelve a comprobar.",
