  "settings.slackBridge.mentionCleanupTitle": "Aún hay que limpiar algunos grupos de usuarios antiguos de Slack",
  "settings.slackBridge.mentionCleanupPending": "Los miembros actuales ya están disponibles en el menú @ de Slack. Aún hay que limpiar algunos grupos antiguos o duplicados. Raft seguirá reintentando; si Slack se niega a desactivarlos, es posible que un administrador de Slack tenga que retirarlos. La sincronización de mensajes no se ve afectada.",
  "settings.slackBridge.mentionSyncTitle": "Aún no se puede elegir a algunos miembros en el menú @ de Slack",
  "settings.slackBridge.mentionSyncRestricted": "Los mensajes se sincronizan con normalidad, y si escribes en Slack el @nombre de un miembro de Raft, la mención le sigue llegando siempre que nadie más en el canal tenga ese nombre. Para que también aparezcan en el menú @ de Slack, un administrador de Slack debe permitir que los miembros creen grupos de usuarios: Configuración del espacio de trabajo → Permisos → Grupos de usuarios.",
  "settings.slackBridge.mentionSyncMissingScope": "Los mensajes se sincronizan con normalidad, y si escribes en Slack el @nombre de un miembro de Raft, la mención le sigue llegando siempre que nadie más en el canal tenga ese nombre. Para que también aparezcan en el menú @ de Slack, Raft necesita un permiso más de Slack: usa “Actualizar autorización de Slack” más abajo.",
  "settings.slackBridge.mentionSyncNameTaken": "Los mensajes se sincronizan con normalidad, y si escribes en Slack el @nombre de un miembro de Raft, la mención le sigue llegando siempre que nadie más en el canal tenga ese nombre. {count, plural, one {# miembro no pudo} other {# miembros no pudieron}} aparecer en el menú @ de Slack porque todos los nombres que probó Raft ya están en uso en Slack. Para solucionarlo, cambia el nombre en Raft o libera el nombre en Slack.",
  "settings.slackBridge.mentionSyncGeneric": "Los mensajes se sincronizan con normalidad, y si escribes en Slack el @nombre de un miembro de Raft, la mención le sigue llegando siempre que nadie más en el canal tenga ese nombre. Slack se negó a incluir a algunos de ellos en su menú @ ({code}); Raft seguirá reintentando.",
