  // pages.deviceLoginRevoke — DeviceLoginRevokePage.tsx — a device login's revoke link (mailed after approving).
  "pages.deviceLoginRevoke.title": "Revocar un inicio de sesión del dispositivo",
  "pages.deviceLoginRevoke.description": "Esto cierra la sesión del programa al que dejaste iniciar sesión con un inicio de sesión del dispositivo, o cancela el inicio de sesión si aún no terminó. Después ya no podrá usar tu cuenta.",
  "pages.deviceLoginRevoke.revoke": "Revocar este inicio de sesión",
  "pages.deviceLoginRevoke.revoking": "Revocando…",
  "pages.deviceLoginRevoke.revokedTitle": "Inicio de sesión del dispositivo revocado",
  "pages.deviceLoginRevoke.revokedDescription": "Se cerró la sesión de ese programa, y las credenciales de agentes y las conexiones de computadoras que configuró dejan de funcionar. Si no iniciaste tú este inicio de sesión, cambia o restablece también tu contraseña para cerrar la sesión en todos los dispositivos, y revisa las credenciales de tus agentes y tus computadoras.",
  "pages.deviceLoginRevoke.revokedSessionUnknown": "Ese inicio de sesión está revocado, pero aquí no se encontró la sesión que abrió. Cambia o restablece tu contraseña para cerrar la sesión en todos los dispositivos, y revisa las credenciales de tus agentes y tus computadoras.",
  "pages.deviceLoginRevoke.linkUsed": "Este enlace ya se usó, así que ese inicio de sesión del dispositivo ya está revocado.",
  "pages.deviceLoginRevoke.linkExpired": "Este enlace ha caducado. Para cerrar la sesión en todos los dispositivos, cambia o restablece tu contraseña.",
  "pages.deviceLoginRevoke.linkInvalid": "Este enlace no es válido. Para cerrar la sesión en todos los dispositivos, cambia o restablece tu contraseña.",
  "pages.deviceLoginRevoke.failedFallback": "No se pudo revocar el inicio de sesión. Inténtalo de nuevo.",
  "pages.deviceLoginRevoke.goToRaft": "Ir a Raft",
  // A Computer's revoke link (dvcr_*, mailed with "You added X to Y"): it revokes that one machine.
  "pages.deviceLoginRevoke.computerTitle": "Revocar una computadora",
  "pages.deviceLoginRevoke.computerDescription": "Esto revoca la clave de la máquina que agregaste a un servidor y las claves de los agentes que ejecuta, y la desconecta. Tus otras computadoras y tus inicios de sesión no se ven afectados.",
  "pages.deviceLoginRevoke.computerRevoke": "Revocar esta máquina",
  "pages.deviceLoginRevoke.computerRevoking": "Revocando la máquina…",
  "pages.deviceLoginRevoke.computerRevokedTitle": "Máquina revocada",
  "pages.deviceLoginRevoke.computerRevokedDescription": "La clave de esa máquina y las claves de sus agentes dejaron de funcionar, y se desconectó. Solo vuelve si alguien la agrega de nuevo. Si no la agregaste tú, cambia o restablece también tu contraseña, y revisa tus computadoras.",
