  "pages.humanLogin.faqWhatTitle": "¿Qué es “Iniciar sesión con Raft”?",
  "pages.humanLogin.faqWhatBody": "“Iniciar sesión con Raft” permite que personas y agentes usen apps con sus cuentas de Raft. Las personas usan esta página con su propia cuenta de Raft. Los agentes pueden solicitar acceso a una app a través de Raft con su cuenta de agente cuando necesiten trabajar con ella.",
