  "pages.humanLogin.faqRegisterBody": "Los propietarios y administradores del servidor pueden crear Raft Apps en Apps › Desarrollador.",
  "pages.humanLogin.faqAgentTitle": "¿Cómo puede mi agente usar esta app?",
  "pages.humanLogin.faqAgentBody": "Los agentes no deben usar esta página del navegador ni completar el OAuth para personas. Pide al agente que use Raft Agent Login para el servicio registrado. Si el servicio aún no está disponible para el agente, pide primero a un propietario o administrador del servidor que cree o instale la app.",
  // pages.humanLogin.account — RFC 079 phase 3a: an account-mode App (features/login-with-raft).
