  "migration.error.capabilityInsufficient": "Ambas computadoras deben ejecutar una versión compatible de Raft Computer y admitir el runtime de este agente. Actualízalas o vuelve a conectarlas, o elige otra computadora, e inténtalo de nuevo.",
  "migration.error.targetOffline": "La computadora de destino está sin conexión. Inicia Raft Computer en ella e inténtalo de nuevo.",
  "migration.error.hostedUnavailable": "Por ahora no se pueden mover agentes a la nube en este servidor. Inténtalo de nuevo más tarde o mueve el agente a una computadora.",
  "migration.error.hostedAlreadyUsed": "Este agente ya se ejecutó en la nube, así que no puede volver a moverse allí.",
  "migration.error.hostedModelInvalid": "Ese modelo no está disponible para agentes en la nube en este servidor. Elige otro modelo o deja el predeterminado.",
  "migration.error.hostedReviewNotReady": "Esta migración ya no está esperando tu confirmación. Actualiza la página para ver en qué estado está.",
  "migration.error.hostedMemoryUnimportable": "El MEMORY.md del agente no se puede llevar a la nube: es demasiado grande, no es texto sin formato o la nube lo rechazó. Pide al agente que recorte MEMORY.md y lo deje en texto sin formato, e inténtalo de nuevo.",
  "migration.error.notCancelable": "El agente ya se movió a la nube, así que esta migración ya no se puede cancelar.",
  "migration.error.targetRuntimeDetectionPending": "La computadora de destino todavía está detectando sus runtimes. Inténtalo de nuevo en un momento.",
  "migration.error.targetRuntimeDetectionIncomplete": "La última detección de runtimes de la computadora de destino no terminó para {runtime}. Vuelve a escanear sus runtimes en la página de la computadora e inténtalo de nuevo.",
  "migration.error.alreadyInProgress": "Este agente ya tiene una migración en curso. Espera a que termine antes de volver a intentarlo.",
  "migration.error.proPlanRequired": "La migración de agentes requiere el plan Pro. Mejora este servidor a Pro antes de volver a intentarlo.",
  "migration.error.transportNotProvisioned": "Raft no pudo preparar una transferencia segura entre estas computadoras. Asegúrate de que ambas estén en línea y actualizadas, e inténtalo de nuevo.",
  "migration.error.transportProvisionFailed": "Raft no pudo preparar la transferencia. Asegúrate de que ambas computadoras estén en línea e inténtalo de nuevo.",
  "migration.error.transportLost": "La conexión entre las dos computadoras se cortó durante la transferencia. Asegúrate de que ambas estén en línea e inténtalo de nuevo.",
  "migration.error.transportLostEvent": "La conexión entre las dos computadoras se cortó durante la transferencia.",
  "migration.error.transportLostAt": "La conexión entre las dos computadoras se cortó el {time}, durante la transferencia.",
  "migration.error.transportLostRetryReady": "Ambas computadoras ya están en línea, así que puedes volver a intentarlo.",
  "migration.error.transportLostRetryOneOffline": "Asegúrate de que {computer} esté en línea y vuelve a intentarlo.",
  "migration.error.transportLostRetryBothOffline": "Asegúrate de que {source} y {target} estén en línea y vuelve a intentarlo.",
  "migration.error.transportLostRetryUnknown": "Comprueba que ambas computadoras estén en línea y vuelve a intentarlo.",
  "migration.error.entryCountLimitExceeded": "El espacio de trabajo tiene demasiados archivos y carpetas para moverlo. Pide al agente que elimine las carpetas que ya no necesite o que las agregue a .raftmigrateignore, e inténtalo de nuevo.",
  "migration.error.entryCountLimitExceededWithDetails": "El espacio de trabajo tiene {count, number} archivos y carpetas; la migración admite hasta {limit, number}.{paths, select, none {} other { La mayoría están en {paths}.}} Pide al agente que elimine las carpetas que ya no necesite o que las agregue a .raftmigrateignore, e inténtalo de nuevo.",
  "migration.error.workspaceAlreadyExists": "La computadora de destino no pudo instalar el agente porque ese espacio de trabajo ya existe. Comprueba qué copia es la actual; mueve el espacio de trabajo en conflicto o haz una copia de seguridad, e inténtalo de nuevo. Raft no lo eliminará automáticamente.",
  "migration.error.workspaceCompleteOldCopy": "La computadora de destino encontró una copia completa anterior de este espacio de trabajo y se detuvo antes de reemplazarla. Confirma qué copia es la actual; mueve la copia antigua o haz una copia de seguridad, e inténtalo de nuevo. Raft no la eliminará automáticamente.",
  "migration.error.workspaceAlreadyExistsAt": "Ya existe un espacio de trabajo en {path} en la computadora de destino, así que no se instaló el agente. Cambia el nombre de esa carpeta o muévela (por ejemplo, basta con agregar .bak al nombre) y vuelve a iniciar la migración. Antes de moverla, comprueba que no sea una copia que todavía necesites: Raft nunca la elimina y, si la mueves, sigue en esa computadora.",
  "migration.error.workspaceCompleteOldCopyAt": "En {path}, en la computadora de destino, hay una copia completa de este espacio de trabajo de una migración anterior, así que Raft se detuvo en lugar de reemplazarla. Cambia el nombre de esa carpeta o muévela (por ejemplo, basta con agregar .old al nombre) y vuelve a iniciar la migración. Antes de moverla, comprueba qué copia es la actual: Raft nunca la elimina y, si la mueves, sigue en esa computadora.",
  "migration.error.controlManifestInvalid": "La computadora de origen generó metadatos de transferencia que la computadora de destino no pudo verificar. Actualiza Raft Computer en ambas computadoras e inténtalo de nuevo.",
  "migration.error.refInvalid": "Falta la referencia de la migración o no es válida. Actualiza el estado de la migración antes de volver a intentarlo.",
  "migration.error.revisionInvalid": "El estado de la migración está incompleto. Actualízalo antes de volver a intentar la cancelación.",
  "migration.error.notFound": "Esta migración ya no está disponible. Actualiza el estado de la migración.",
  "migration.error.revisionStale": "La migración cambió antes de que se completara esta acción. Actualiza la página e inténtalo de nuevo.",
  "migration.error.concurrentUpdate": "Otra operación modificó la migración al mismo tiempo. Actualiza la página e inténtalo de nuevo.",
  "migration.error.cancelFailed": "Raft no pudo solicitar la cancelación. Actualiza el estado de la migración e inténtalo de nuevo.",
  "migration.error.startFailed": "No se pudo iniciar la migración. Revisa ambas computadoras e inténtalo de nuevo.",
  "migration.error.statusFailed": "No se pudo cargar el estado de la migración. Actualiza la página e inténtalo de nuevo.",
  "migration.error.objectStoreUnreachable": "Una de las computadoras no pudo acceder al almacenamiento de migración de Raft durante 5 minutos. Revisa su red, proxy o firewall e inténtalo de nuevo.",
  "migration.error.computerOwnerDeleted": "La migración se detuvo porque el propietario de una de sus computadoras eliminó su cuenta de Raft. Mueve el agente a otra computadora.",
  "migration.error.targetComputerDetached": "Esta migración se detuvo porque la computadora de destino se desvinculó antes de que el agente pudiera moverse a ella. El agente se queda donde estaba; elige otra computadora.",
  "migration.error.transferSummaryInvalid": "El ordenador de origen no pudo contar los archivos excluidos de esta migración. Actualiza Raft Computer en el ordenador de origen a la última versión y vuelve a intentarlo.",
